def categorize_tags(tags):
    if not tags:
        return 'empty'
    if 'python' in tags and 'ai' in tags:
        return 'tech'
    elif 'python' in tags:
        return 'programming' if len(tags) == 1 else 'mixed'
    else:
        return 'other'

# Example usage
print(categorize_tags(['python', 'ai']))

price = float(input('Item price: '))
quantity = int(input('Quantity: '))
code = input('Discount code (or press Enter): ')

if price < 0 or quantity <= 0:
    print('Error: Invalid price or quantity')
else:
    total = price * quantity
    if code == 'SAVE10':
        total *= 0.9
    elif code == 'SAVE20':
        total *= 0.8
    elif code:
        print('Error: Unknown discount code')
    else:
        pass
    print(f'Final price: {total:.2f}')

def grade_report(scores):
    if all(s >= 60 for s in scores):
        return 'All passed'
    elif any(s >= 90 for s in scores):
        return 'Top performer'
    else:
        return 'Needs improvement'

# Test
print(grade_report([70, 80, 90]))   # Top performer
print(grade_report([55, 65, 75]))   # Needs improvement
print(grade_report([85, 92, 78]))  # Top performer
print(grade_report([60, 60, 60]))  # All passed
